/* STM32CubeU5 HAL clock initialisation test.
 *
 * Runs the HAL calls generated by STM32CubeMX for a 160 MHz system clock from MSIS + PLL1 on
 * STM32U575: HAL_Init, voltage scaling range 1, HAL_RCC_OscConfig, HAL_RCC_ClockConfig with
 * four flash wait states, and ICACHE enable. The result of every call is stored in a global
 * variable that the robot test reads through the ELF symbol table. The HAL is unmodified. */

#include "stm32u5xx_hal.h"

enum
{
    StepInit = 1,
    StepVoltageScaling = 2,
    StepOscillators = 3,
    StepClocks = 4,
    StepIcache = 5,
    StepDelay = 6,
    StepDone = 7,
};

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t halStatus;
volatile uint32_t sysclkHz;
volatile uint32_t hclkHz;
volatile uint32_t pclk1Hz;
volatile uint32_t pclk2Hz;
volatile uint32_t pclk3Hz;
volatile uint32_t systemCoreClockHz;
volatile uint32_t tickBeforeDelay;
volatile uint32_t tickAfterDelay;
volatile uint32_t loopCount;

void SysTick_Handler(void)
{
    HAL_IncTick();
}

static void check(HAL_StatusTypeDef status, uint32_t currentStep)
{
    step = currentStep;
    if (status != HAL_OK)
    {
        halStatus = (uint32_t)status;
        failedStep = currentStep;
        for (;;)
        {
        }
    }
}

static void systemClockConfig(void)
{
    RCC_OscInitTypeDef oscillators = {0};
    RCC_ClkInitTypeDef clocks = {0};

    __HAL_RCC_PWR_CLK_ENABLE();
    check(HAL_PWREx_ControlVoltageScaling(PWR_REGULATOR_VOLTAGE_SCALE1), StepVoltageScaling);

    oscillators.OscillatorType = RCC_OSCILLATORTYPE_MSI;
    oscillators.MSIState = RCC_MSI_ON;
    oscillators.MSICalibrationValue = RCC_MSICALIBRATION_DEFAULT;
    oscillators.MSIClockRange = RCC_MSIRANGE_4;
    oscillators.PLL.PLLState = RCC_PLL_ON;
    oscillators.PLL.PLLSource = RCC_PLLSOURCE_MSI;
    oscillators.PLL.PLLMBOOST = RCC_PLLMBOOST_DIV1;
    oscillators.PLL.PLLM = 1;
    oscillators.PLL.PLLN = 80;
    oscillators.PLL.PLLP = 2;
    oscillators.PLL.PLLQ = 2;
    oscillators.PLL.PLLR = 2;
    oscillators.PLL.PLLRGE = RCC_PLLVCIRANGE_0;
    oscillators.PLL.PLLFRACN = 0;
    check(HAL_RCC_OscConfig(&oscillators), StepOscillators);

    clocks.ClockType = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK | RCC_CLOCKTYPE_PCLK1 |
                       RCC_CLOCKTYPE_PCLK2 | RCC_CLOCKTYPE_PCLK3;
    clocks.SYSCLKSource = RCC_SYSCLKSOURCE_PLLCLK;
    clocks.AHBCLKDivider = RCC_SYSCLK_DIV1;
    clocks.APB1CLKDivider = RCC_HCLK_DIV1;
    clocks.APB2CLKDivider = RCC_HCLK_DIV1;
    clocks.APB3CLKDivider = RCC_HCLK_DIV1;
    check(HAL_RCC_ClockConfig(&clocks, FLASH_LATENCY_4), StepClocks);
}

int main(void)
{
    check(HAL_Init(), StepInit);
    systemClockConfig();

    check(HAL_ICACHE_ConfigAssociativityMode(ICACHE_1WAY), StepIcache);
    check(HAL_ICACHE_Enable(), StepIcache);

    sysclkHz = HAL_RCC_GetSysClockFreq();
    hclkHz = HAL_RCC_GetHCLKFreq();
    pclk1Hz = HAL_RCC_GetPCLK1Freq();
    pclk2Hz = HAL_RCC_GetPCLK2Freq();
    pclk3Hz = HAL_RCC_GetPCLK3Freq();
    systemCoreClockHz = SystemCoreClock;

    step = StepDelay;
    tickBeforeDelay = HAL_GetTick();
    HAL_Delay(10);
    tickAfterDelay = HAL_GetTick();

    step = StepDone;
    for (;;)
    {
        loopCount += 1u;
    }
}
